// === Tab: mySketch ===
// by SamuelYAN
// more works //
   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/
// LinearGradient + rect + circle

let mySize;
let seed = Math.random() * 2000;

// colors
let colors1 = "e3d7a3-f5989d-ea618e-fce4d6-caac71"
  .split("-")
  .map((a) => "#" + a);
let colors2 = "7d483e-b87644-e6d2c9-e45e00-905c40"
  .split("-")
  .map((a) => "#" + a);

function setup() {
  pixelDensity(5);
  //mySize = 600;
  mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  randomSeed(seed);
  background(5);
}

function draw() {
  randomSeed(seed);
  noStroke();
  let col1 = random(colors1);
  let col2 = random(colors1);
  var gradbg = drawingContext.createLinearGradient(0, 0, width, 0);
  gradbg.addColorStop(0, col1);
  gradbg.addColorStop(1, col2);
  drawingContext.fillStyle = gradbg;
  rect(0, 0, width, height);

  push();
  translate(width / 2, height / 2);
  let col3 = random(colors1);
  let col4 = random(colors1);
  let circleR = width / 1.5;
  var grad = drawingContext.createLinearGradient(
    0,
    0,
    -circleR / 2,
    -circleR / 2
  );
  grad.addColorStop(0, col3);
  grad.addColorStop(1, col4);
  drawingContext.fillStyle = grad;
  drawingContext.shadowColor = color(0, 0, 0, 20);
  drawingContext.shadowOffsetX = 20;
  drawingContext.shadowOffsetY = 20;
  drawingContext.shadowBlur = 100;
  circle(0, 0, circleR);
  pop();
}

function mouseClicked() {
  seed = Math.random() * 1000;
  randomSeed(seed);
  loop();
}

function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("MovingShapes-bg", "png");
  }
}

